// Setzwerk helpers of the workspace: source-line map from the compiler's comments, error texts.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { setzErrorText, setzLineMap } from '../../web/js/views/workspace.js';
import de from '../../web/js/texts/de.js';
import en from '../../web/js/texts/en.js';
import { createI18n } from '../../web/js/i18n.js';

const ASM = [
  '; Generated by the Setzwerk compiler from x.sz.',
  '',
  '; fn f(a)',
  'f:',
  '        push fp                 ; prologue',
  '        ; line 3: return a;',
  '        ld r0, [fp - 4]          ; a',
  '        jmp .exit',
  '.exit:',
  '        ret',
  '; fn main()',
  'main:',
  '        ; Zeile 7: print(1);',
  '        mov r0, 1',
].join('\n');

test('setzLineMap follows "; line N:" and "; Zeile N:" and leaves prologue and epilogue out', () => {
  assert.deepEqual([...setzLineMap(ASM)], [[6, 3], [7, 3], [8, 3], [13, 7], [14, 7]]);
});

test('setzErrorText translates the found token and the kind of name', () => {
  const tde = createI18n('de', de).t;
  const ten = createI18n('en', en).t;
  const err = { key: 'setz.expected_token', line: 2, col: 13, args: { token: ';', found: '}' } };
  assert.equal(setzErrorText(tde, err), 'Hier fehlt „;“, gefunden: „}“.');
  assert.equal(setzErrorText(ten, err), "';' is missing here, found '}'.");
  assert.match(setzErrorText(tde, { key: 'setz.expected_expr', args: { found: '' } }), /das Dateiende/);
  assert.match(setzErrorText(ten, { key: 'setz.expected_name', args: { what: 'fn', found: '12' } }), /Expected a function name here, found the number 12/);
});
